    assert [(r["term_name"], r["class_name"]) for r in rows] == [("iclaprim", "penicillin beta-lactam")]
    notes = [r for r in table(release, "catalogue_log") if r["chembl_id"] == "CHEMBL5" and r["kind"] == "note"]
    assert "cefdinir" in notes[0]["reason"]


